      (t,i)=>({q:'Identifica o equivalente em inglês de “'+t[1]+'”.',opts:[t[0],'unrelated expression','incorrect form'],a:0,explanation:'A expressão correspondente é “'+t[0]+'”.'}),
      (t,i)=>({q:'Em que situação usarias “'+t[0]+'”?',opts:['Quando o contexto exige a ideia de “'+t[1]+'”.','Para expressar o significado oposto.','Em qualquer frase sem considerar o contexto.'],a:0,explanation:'O contexto determina o uso adequado da palavra.'})
